export default function FrancisOfAssisi({
  p,
  detail,
}: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        {/* Stable white paper underneath every paint region. */}
        <rect
          x="0"
          y="0"
          width="1024"
          height="1536"
          fill={PAPER}
          pointerEvents="none"
        />

        {/* Sky / distant landscape base. */}
        <g {...p('background')} stroke="none">
          <rect x="0" y="0" width="1024" height="1536" />
        </g>

        {/* Right cloud bank. The left cloud bank is part of the open sky region
            in the source drawing, so its exact outline remains in the ink layer. */}
        <g {...p('cloud')} stroke="none">
          <path d={CLOUD_MASK} />
        </g>

        {/* Double halo and the open halo field behind the head. */}
        <g {...p('halo')} stroke="none">
          <path d={HALO_MASK} />
        </g>

        {/* Hood/cowl and both wide sleeves. */}
        <g {...p('mantle')} stroke="none">
          <path d={MANTLE_MASK} />
        </g>

        {/* Main habit body, including the long lower robe. */}
        <g {...p('robe')} stroke="none">
          <path d={ROBE_MASK} />
        </g>

        {/* Face, neck, ear and both hands.
            Drawn before hair so hair slightly overlaps the skin boundary. */}
        <g {...p('skin')} stroke="none">
          <path d={SKIN_MASK} />
        </g>

        {/* Hair, side curls, moustache and beard. */}
        <g {...p('hair')} stroke="none">
          <path d={HAIR_MASK} />
        </g>

        {/* Franciscan cord / belt and hanging knots. */}
        <g {...p('accent')} stroke="none">
          <path d={ACCENT_MASK} />
        </g>

        {/* Birds plus the foreground leaves / flowers. */}
        <g {...p('symbol')} stroke="none">
          <path d={SYMBOL_MASK} />
        </g>

        {/* Exact traced black line art from the supplied Francis image.
            IMPORTANT: this must stay last and non-interactive. */}
        <path
          {...detail}
          {...ink}
          d={FRANCIS_LINE_ART}
          fill={STROKE}
          stroke="none"
          fillRule="evenodd"
          pointerEvents="none"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}